// Package adrindex generates docs/decisions/INDEX.md from the records' front matter (ADR 0067). scripts/adrlint
// (index --write and --check) and scripts/releasecheck (the INDEX.md at the release commit) share it.
package adrindex

import (
	"fmt"
	"regexp"
	"sort"
	"strings"
)

// Header is the first line of the generated file.
const Header = "<!-- generated by scripts/adrlint index --write; do not edit -->"

// NameRE matches an ADR file name, NNNN-kebab-title.md.
var NameRE = regexp.MustCompile(`^(\d{4})-[a-z0-9]+(?:-[a-z0-9]+)*\.md$`)

// File is one record: its file name in the decisions directory and its content.
type File struct {
	Name    string
	Content string
}

// Generate returns the INDEX.md for the records, sorted by number. Names that are not ADR file names are skipped.
func Generate(files []File) string {
	fs := make([]File, 0, len(files))
	for _, f := range files {
		if NameRE.MatchString(f.Name) {
			fs = append(fs, f)
		}
	}
	sort.Slice(fs, func(i, j int) bool { return fs[i].Name < fs[j].Name })
	var b strings.Builder
	b.WriteString(Header + "\n\n")
	b.WriteString("| ADR | Title | Status | Date |\n|---|---|---|---|\n")
	for _, f := range fs {
		status, date, title := parse(f.Content)
		if title == "" {
			title = strings.TrimSuffix(f.Name, ".md")
		}
		fmt.Fprintf(&b, "| [%s](%s) | %s | %s | %s |\n", f.Name[:4], f.Name, cell(title), cell(status), cell(date))
	}
	return b.String()
}

func cell(s string) string { return strings.ReplaceAll(s, "|", `\|`) }

// parse returns the status (a long note after ";" collapsed), the date and the first heading of a record.
func parse(content string) (status, date, title string) {
	lines := strings.Split(strings.ReplaceAll(content, "\r\n", "\n"), "\n")
	body := 0
	if len(lines) > 0 && strings.TrimSpace(lines[0]) == "---" {
		for i := 1; i < len(lines); i++ {
			if strings.TrimSpace(lines[i]) == "---" {
				body = i + 1
				break
			}
			k, v, ok := strings.Cut(lines[i], ":")
			if !ok || strings.HasPrefix(lines[i], " ") {
				continue
			}
			v = strings.Trim(strings.TrimSpace(v), `"'`)
			switch strings.TrimSpace(k) {
			case "status":
				status = v
			case "date":
				date = v
			}
		}
	}
	if i := strings.Index(status, ";"); i >= 0 {
		status = strings.TrimSpace(status[:i])
	}
	inFence := false
	for _, ln := range lines[body:] {
		if strings.HasPrefix(strings.TrimSpace(ln), "```") {
			inFence = !inFence
			continue
		}
		if !inFence && strings.HasPrefix(ln, "# ") {
			title = strings.TrimSpace(ln[2:])
			break
		}
	}
	return status, date, title
}
